import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/cash/data/cash_repository.dart';import 'package:pos_app/shared/presentation/database_list_screen.dart';class CashScreen extends StatelessWidget{const CashScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Caja')),body:Column(children:[Expanded(child:DatabaseListScreen(title:'Sesiones',query:'SELECT id,opened_at,opening_balance_cents,status,difference_cents FROM cash_sessions ORDER BY id DESC')),Padding(padding:const EdgeInsets.all(12),child:Wrap(spacing:12,children:[FilledButton(onPressed:()async{final v=await textForm(context,'Abrir caja',['Saldo inicial centavos']);if(v!=null)await CashRepository(appDatabase).open(int.parse(v[0]));},child:const Text('Abrir')),OutlinedButton(onPressed:()async{final v=await textForm(context,'Cerrar caja',['Efectivo contado centavos']);if(v!=null)await CashRepository(appDatabase).close(int.parse(v[0]));},child:const Text('Cerrar'))]))]));}
